<template><div><h2>{{title}}</h2><el-card><el-table :data="items" v-loading="loading" stripe><el-table-column v-for="column in columns" :key="column" :prop="column" :label="labels[column] || column" /></el-table><el-empty v-if="!loading&&!items.length" description="暂无数据" /></el-card></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue'; import {api} from '../../api'; const props=defineProps<{title:string; kind:string}>(); const items=ref<Record<string,unknown>[]>([]); const loading=ref(true); const columns=ref<string[]>([]); const labels:Record<string,string>={name:'名称',code:'编号',status:'状态',level:'等级',intersectionId:'路口',type:'类型',volume:'流量',speed:'速度',queue:'排队长度',title:'事件标题',objective:'优化目标'}; onMounted(async()=>{try{const result=props.kind==='roads'?await api.roads():props.kind==='intersections'?await api.intersections():props.kind==='plans'?await api.plans():props.kind==='readings'?await api.readings():await api.events(); items.value=result.data.data.items||result.data.data||[]; columns.value=items.value.length?Object.keys(items.value[0]).filter(k=>!['id','createdAt','updatedAt'].includes(k)).slice(0,8):[]}finally{loading.value=false}})</script>
